(function(){'use strict';var currentFrame=null;function post(command){if(currentFrame&&currentFrame.contentWindow)currentFrame.contentWindow.postMessage(Object.assign({source:'nawaf-hq-dashboard'},command),'*')}function boot(){var wrap=document.querySelector('.hq-3d-stage');if(!wrap||wrap.dataset.v17Live==='1')return;wrap.dataset.v17Live='1';var old=wrap.querySelector('.office-scene');if(old)old.remove();var frame=document.createElement('iframe');frame.src='hq-office-live.html?v=17-main-controls';frame.className='live-office-frame';frame.title='NAWAF HQ live office V17';frame.style.position='absolute';frame.style.inset='0';frame.style.width='100%';frame.style.height='100%';frame.style.border='0';frame.style.zIndex='2';frame.style.background='#101720';wrap.prepend(frame);currentFrame=frame;wrap.querySelectorAll('.room-nav,.scene-brand,.scene-status').forEach(function(n){n.style.display='none'});wrap.style.minHeight='620px'}window.NawafHQ3D={boot:boot,mode:function(mode){post({action:'mode',mode:mode})},meeting:function(){post({action:'meeting'})},review:function(){post({action:'review'})},collab:function(){post({action:'collab'})},work:function(){post({action:'work'})},assignTask:function(employeeId,taskType){post({action:'assignTask',employeeId:employeeId,taskType:taskType})}};function start(){setTimeout(boot,120)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();window.addEventListener('message',function(e){var m=e.data||{};if(m.source!=='nawaf-hq-office'||!m.type)return;window.dispatchEvent(new CustomEvent(m.type,{detail:m.detail||{}}));if(m.type==='hq:office-ready')window.dispatchEvent(new CustomEvent('nawaf:office-ready',{detail:m.detail||{}}))});window.addEventListener('nawaf:state-updated',function(){var w=document.querySelector('.hq-3d-stage');if(w){w.dataset.v17Live='';var f=w.querySelector('.live-office-frame');if(f)f.remove();currentFrame=null;setTimeout(boot,120)}})})();